//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::float::scaleb`; the
//! native twin is `benches/native/Bench/FloatScaleb.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::float;
use lean_runtime_bench::{run, step, SEED};

#[allow(unused_variables)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0.0f64);
    for _ in 0..n {
        x = step(x);
        acc += float::scaleb(
            (-100.0 + ((x >> 11) as f64 * (1.0 / 9007199254740992.0)) * 200.0),
            (((x >> 8) & 0x7ff) as i64 - 1024),
        );
    }
    float::to_bits(acc) as u64
}

fn main() {
    run(|| (), kernel)
}
